UPDATE datasets SET validated=1 WHERE id='f331e13b01a663af' AND (SELECT COUNT(*) FROM employees WHERE dataset_id='f331e13b01a663af')=174 AND (SELECT COUNT(*) FROM courses WHERE dataset_id='f331e13b01a663af')=10 AND (SELECT COUNT(*) FROM completions WHERE dataset_id='f331e13b01a663af')=2860 AND (SELECT COUNT(*) FROM sessions WHERE dataset_id='f331e13b01a663af')=34 AND (SELECT COUNT(*) FROM audit WHERE dataset_id='f331e13b01a663af')=4434;
INSERT INTO active_dataset(singleton,dataset_id) SELECT 1,id FROM datasets WHERE id='f331e13b01a663af' AND validated=1 ON CONFLICT(singleton) DO UPDATE SET dataset_id=excluded.dataset_id;
